import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { log } from '../src/log.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ordersPath = path.join(__dirname, '../data/orders.json');
const data = JSON.parse(fs.readFileSync(ordersPath, 'utf-8'));

const customerTotals = {};

for (const order of data) {
  if (!customerTotals[order.customer]) {
    customerTotals[order.customer] = 0;
  }
  customerTotals[order.customer] += order.amount;
}

const sorted = Object.entries(customerTotals)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3);

for (const [customer, total] of sorted) {
  const euros = (total / 100).toFixed(2);
  log(`${customer}: €${euros}`);
}

