const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ordersPath = path.join(__dirname, '../data/orders.json');
const data = JSON.parse(fs.readFileSync(ordersPath, 'utf-8'));

const searchText = process.argv[2];

if (!searchText) {
  log('Usage: node scripts/search.js <text>');
  process.exit(1);
}

const matches = data.filter(order =>
  order.customer.toLowerCase().includes(searchText.toLowerCase())
);

if (matches.length === 0) {
  log('no matches');
} else {
  for (const order of matches) {
    const euros = (order.amount / 100).toFixed(2);
    log(`${order.id}: ${order.customer} - €${euros} (${order.date})`);
  }
}

